auto getHeight = [&](TreeNode* n) -> int {
    return n ? n->height : 0;
};
auto updateHeight = [&](TreeNode* n) {
    if (n) n->height = 1 + std::max(getHeight(n->left), getHeight(n->right));
};
auto getBalance = [&](TreeNode* n) -> int {
    return n ? getHeight(n->left) - getHeight(n->right) : 0;
};
auto rightRotate = [&](TreeNode* y) -> TreeNode* {
    TreeNode* x = y->left;
    TreeNode* T2 = x->right;
    x->right = y;
    y->left = T2;
    updateHeight(y);
    updateHeight(x);
    return x;
};
auto leftRotate = [&](TreeNode* x) -> TreeNode* {
    TreeNode* y = x->right;
    TreeNode* T2 = y->left;
    y->left = x;
    x->right = T2;
    updateHeight(x);
    updateHeight(y);
    return y;
};
auto minValueNode = [&](TreeNode* node) -> TreeNode* {
    TreeNode* cur = node;
    while (cur && cur->left) cur = cur->left;
    return cur;
};

if (!root) return;

if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    // node with only one child or no child
    if (!root->left || !root->right) {
        TreeNode* temp = root->left ? root->left : root->right;
        delete root;
        root = temp;
    } else {
        // node with two children: get inorder successor
        TreeNode* succ = minValueNode(root->right);
        root->data = succ->data;
        avlDelete(root->right, succ->data);
    }
}

if (!root) return;

updateHeight(root);
int balance = getBalance(root);

// Left Left Case
if (balance > 1 && getBalance(root->left) >= 0) {
    root = rightRotate(root);
}
// Left Right Case
else if (balance > 1 && getBalance(root->left) < 0) {
    root->left = leftRotate(root->left);
    root = rightRotate(root);
}
// Right Right Case
else if (balance < -1 && getBalance(root->right) <= 0) {
    root = leftRotate(root);
}
// Right Left Case
else if (balance < -1 && getBalance(root->right) > 0) {
    root->right = rightRotate(root->right);
    root = leftRotate(root);
}

